<script setup>
import {ref,computed,onMounted,onUnmounted,watch,nextTick} from 'vue'
import {useRoute,useRouter} from 'vue-router'
import {ElMessage} from 'element-plus'
import {ChatDotRound,Document,ArrowRight,Shop,Refresh,Picture,Close,Plus,Clock,InfoFilled} from '@element-plus/icons-vue'
import request from '@/utils/request'
import ServiceUpload from '@/components/ServiceUpload.vue'
import ServiceAttachment from '@/components/ServiceAttachment.vue'
import {serviceConnection,isBackendMode} from '@/utils/service-mode'
import {serviceKey} from '@/utils/service-files'
import {mergeMessages,refreshHistory} from '@/utils/service-history'
const props=defineProps({mode:{type:String,default:'support'}})
const route=useRoute(),router=useRouter(),overview=ref({sessions:[],tickets:[],counts:{}}),shops=ref([]),orders=ref([]),thread=ref(null),ticket=ref(null),loaded=ref(false),error=ref(''),busy=ref(false),text=ref(''),attachments=ref([]),uploading=ref(false),picker=ref(false),ticketFilter=ref('ALL'),includeArchived=ref(false),page=ref(1),pageSize=ref(10),historyMore=ref(false),historyBusy=ref(false)
const form=ref({unitId:String(route.query.unitId||''),title:'',content:'',priority:'MEDIUM',orderId:String(route.query.orderId||'')})
const actor=JSON.parse(sessionStorage.getItem('account')||'{}')
let currentKey='',currentSignature='',loadVersion=0,timer,disposed=false,contextVersion=0,operationVersion=0,oldPages=0,readBlocked=false
const context=()=>contextVersion+'|'+route.fullPath+'|'+sessionStorage.getItem('account')+'|'+serviceConnection.revision
const current=stamp=>!disposed&&context()===stamp
const labels={OPEN:'待处理',IN_PROGRESS:'处理中',RESOLVED:'已回复解决',CLOSED:'已关闭'}
const priorities={HIGH:'高',MEDIUM:'中',LOW:'低',IMPORTANT:'高',NORMAL:'中'}
const historyLabels={CREATE:'提交留言',REPLY:'新增回复',STATUS:'状态更新',ARCHIVE:'移入归档',RESTORE:'恢复留言'}
const time=value=>value?new Date(value).toLocaleString('zh-CN',{month:'numeric',day:'numeric',hour:'2-digit',minute:'2-digit',hour12:false}):''
const go=(page,query)=>router.push({path:'/mall/'+page,query})
const filteredTickets=computed(()=>overview.value.tickets)
const ticketTotal=computed(()=>overview.value.ticketTotal??filteredTickets.value.length)
const relatedOrders=computed(()=>orders.value.filter(o=>String(o.unitId)===String(form.value.unitId)))
const userLoggedIn=computed(()=>actor.role==='ROLE_USER')
const remote=computed(()=>isBackendMode())
const sessionId=()=>String(route.query.id||'')
const relatedChatOrder=computed(()=>orders.value.find(o=>String(o.id)===String(route.query.orderId||'')&&String(o.unitId)===String(thread.value?.session?.unitId)))
const media=row=>row?.attachments?.length?row.attachments:row?.attachment?[row.attachment]:[]
const submissionKey=(action,payload)=>{const signature=JSON.stringify([action,payload]);if(signature!==currentSignature){currentSignature=signature;currentKey=serviceKey(action)}return currentKey}

async function load(){
 const version=++loadVersion,stamp=context(),view=props.mode,id=sessionId();error.value=''
 const params={page:view==='supportTickets'?page.value:1,limit:view==='supportTickets'?pageSize.value:100,includeArchived:includeArchived.value,...(ticketFilter.value!=='ALL'?{status:ticketFilter.value}:{})}
 const [stores,data,purchases]=await Promise.all([request.get('/unit'),userLoggedIn.value?request.get('/support/overview',{params}):Promise.resolve({code:'200',data:{sessions:[],tickets:[],counts:{}}}),userLoggedIn.value?request.get('/orders/front/page',{params:{pageSize:100}}):Promise.resolve({data:{records:[]}})])
 let detail=null;if(view==='supportChat'&&id)detail=await request.get('/support/session',{params:{id}});if(view==='supportTicket'&&id)detail=await request.get('/support/ticket',{params:{id}})
 if(version!==loadVersion||!current(stamp))return
 shops.value=stores.data||[];overview.value=data.data||{sessions:[],tickets:[],counts:{}};orders.value=purchases.data?.records||[]
 if(data.code!=='200')error.value=data.msg;if(detail&&detail.code!=='200')error.value=detail.msg
 let readable=true
 if(view==='supportChat'&&detail?.data){
  const prior=oldPages&&String(thread.value?.session.id)===id?thread.value.messages:[]
  const refreshed=await refreshHistory({prior,latest:detail.data,current:()=>version===loadVersion&&current(stamp),fetchOlder:async beforeId=>{const r=await request.get('/support/session',{params:{id,beforeId}});if(r.code!=='200')throw Error(r.msg);return r.data}}).catch(()=>({messages:detail.data.messages,reset:true,readable:false}))
  if(version!==loadVersion||!current(stamp))return
  readable=refreshed.readable;if(refreshed.reset){oldPages=0;readBlocked=true;error.value='消息历史需要重新读取，请点击读取更早消息；未推进已读位置'}
  thread.value={...detail.data,messages:refreshed.messages};if(!oldPages)historyMore.value=!!detail.data.hasMore
 }else thread.value=null
 ticket.value=view==='supportTicket'?detail?.data:null;loaded.value=true
 const last=thread.value?.messages.at(-1);if(readable&&!readBlocked&&last&&version===loadVersion&&current(stamp)&&document.visibilityState!=='hidden')await request.post('/support/mark-read',{sessionId:id,lastSeenMessageId:String(last.id),clientKey:serviceKey('READ')})
}
async function older(){if(historyBusy.value||!thread.value?.messages.length)return;const stamp=context(),id=sessionId(),beforeId=String(thread.value.messages[0].id);historyBusy.value=true;try{const r=await request.get('/support/session',{params:{id,beforeId}});if(!current(stamp))return;if(r.code!=='200')return ElMessage.error(r.msg);oldPages++;thread.value={...thread.value,messages:mergeMessages(r.data.messages,thread.value.messages)};historyMore.value=!!r.data.hasMore;if(!r.data.hasMore)readBlocked=false}finally{if(current(stamp))historyBusy.value=false}}
async function call(action,payload){if(busy.value||uploading.value)return null;const stamp=context(),operation=++operationVersion;busy.value=true;try{const r=await request.post('/support/'+action,{...payload,clientKey:submissionKey(action,payload)});if(r.code!=='200'){if(current(stamp)){ElMessage.error(r.msg);if(r.code==='409')await load()}return null}if(r.data?.detailError&&current(stamp))ElMessage.warning(r.msg);return r.data}finally{if(operation===operationVersion&&!disposed)busy.value=false}}
async function start(store){if(!userLoggedIn.value)return router.push({path:'/login',query:{returnTo:route.fullPath}});const stamp=context(),r=await call('open-session',{unitId:String(store.id)});if(r&&current(stamp)){picker.value=false;go('supportChat',{id:r.id,...(route.query.orderId?{orderId:String(route.query.orderId)}:{})})}}
async function send(){if(!text.value.trim()&&!attachments.value.length)return;const stamp=context(),draft=text.value,files=JSON.stringify(attachments.value),ids=attachments.value.map(a=>String(a.id));const r=await call('send-message',{sessionId:sessionId(),text:draft,attachmentIds:ids});if(r&&current(stamp)){if(text.value===draft&&JSON.stringify(attachments.value)===files){text.value='';attachments.value=[];currentSignature=''}await load();await nextTick();if(current(stamp)){const box=document.querySelector('.support-messages');box?.scrollTo({top:box.scrollHeight,behavior:'smooth'})}}}
async function submitTicket(){const stamp=context(),draft=JSON.stringify([form.value,attachments.value]),payload={unitId:String(form.value.unitId),title:form.value.title,content:form.value.content,priority:form.value.priority,attachmentIds:attachments.value.map(a=>String(a.id))};if(form.value.orderId)payload.orderId=String(form.value.orderId);const r=await call('create-ticket',payload);if(r&&current(stamp)){if(draft===JSON.stringify([form.value,attachments.value])){attachments.value=[];currentSignature='';go('supportTicket',{id:r.id});ElMessage.success(remote.value?'留言已保存到Java模拟服务':'留言已保存在本机')}else ElMessage.success('上一份留言已保存；当前新草稿继续保留')}}
async function replyTicket(){if(!text.value.trim())return;const stamp=context(),draft=text.value,files=JSON.stringify(attachments.value);const r=await call('reply-ticket',{ticketId:sessionId(),version:ticket.value.version,text:draft,attachmentIds:attachments.value.map(a=>String(a.id))});if(r&&current(stamp)){if(text.value===draft&&JSON.stringify(attachments.value)===files){text.value='';attachments.value=[];currentSignature=''}await load()}}
async function setStatus(status){const stamp=context(),r=await call('ticket-status',{ticketId:ticket.value.id,version:ticket.value.version,status});if(r&&current(stamp)){await load();if(current(stamp))ElMessage.success(status==='OPEN'?'留言已重新打开':'留言已关闭')}}
async function archive(restore=false){const stamp=context(),r=await call(restore?'restore-ticket':'archive-ticket',{ticketId:ticket.value.id,version:ticket.value.version,reason:restore?'顾客恢复自己的留言':'顾客主动移入可恢复归档'});if(r&&current(stamp)){await load();ElMessage.success(restore?'留言已恢复':'已归档，可从含归档列表恢复')}}
const sync=e=>{if(e.key==='mall-ui-data-v2'&&!remote.value)load()}
const visibleRefresh=()=>{if(document.visibilityState!=='hidden')load()}
onMounted(async()=>{await load();if(disposed)return;if(props.mode==='support'&&route.query.unitId){const store=shops.value.find(s=>String(s.id)===String(route.query.unitId));if(store&&userLoggedIn.value)await start(store)}if(disposed)return;timer=setInterval(visibleRefresh,5000);window.addEventListener('storage',sync);window.addEventListener('focus',visibleRefresh);document.addEventListener('visibilitychange',visibleRefresh)})
onUnmounted(()=>{disposed=true;contextVersion++;operationVersion++;loadVersion++;clearInterval(timer);window.removeEventListener('storage',sync);window.removeEventListener('focus',visibleRefresh);document.removeEventListener('visibilitychange',visibleRefresh)})
watch(()=>route.fullPath,()=>{contextVersion++;operationVersion++;busy.value=false;picker.value=false;text.value='';attachments.value=[];uploading.value=false;currentSignature='';oldPages=0;readBlocked=false;historyMore.value=false;historyBusy.value=false;page.value=1;if(props.mode==='supportNew')form.value={unitId:String(route.query.unitId||''),title:'',content:'',priority:'MEDIUM',orderId:String(route.query.orderId||'')};load()})
watch([page,pageSize,ticketFilter,includeArchived],()=>load())
watch(()=>form.value.unitId,()=>{if(!relatedOrders.value.some(o=>String(o.id)===String(form.value.orderId)))form.value.orderId=''})
</script>
<template><div v-if="loaded" class="support-mobile" :class="{'has-composer':mode==='supportChat'}">
<template v-if="mode==='support'">
<section class="support-hero"><small>鲜食好店 · 服务中心</small><h2>有什么可以帮你？</h2><p>联系本店，查看留言与处理进度</p><div class="support-hero-icon"><ChatDotRound/></div></section>
<section class="support-entry-grid"><button @click="picker=true"><span class="peach"><ChatDotRound/></span><strong>联系店铺客服</strong><small>选择商家开始沟通</small></button><button @click="go('supportTickets')"><span class="cream"><Document/></span><strong>我的留言</strong><small>{{overview.ticketTotal??overview.tickets.length}}条{{remote?'服务端':'本机'}}记录</small></button></section>
<section class="native-card"><div class="support-section-title"><h3>最近会话</h3><button aria-label="刷新会话" @click="load"><Refresh/></button></div><button v-for="session in overview.sessions" :key="session.id" class="support-session" @click="go('supportChat',{id:session.id})"><img :src="session.shopAvatar||'/avatar.svg'" alt="店铺头像"/><span><strong>{{session.shopName}}</strong><small>{{session.lastMessage?.text|| (session.lastMessage?.attachment?'[图片]':'暂无消息，发起咨询吧')}}</small></span><b v-if="session.unread">{{session.unread}}</b><ArrowRight/></button><p v-if="!overview.sessions.length" class="support-empty">{{userLoggedIn?'还没有会话，选择一家商家开始咨询':'登录顾客身份后可查看会话和留言'}}</p></section>
<section class="native-card support-help-links"><button @click="go('manuals')"><Document/><span>资料与使用说明</span><ArrowRight/></button><button @click="go('updates')"><Clock/><span>更新记录</span><ArrowRight/></button><button @click="go('profile')"><InfoFilled/><span>个人显示资料</span><ArrowRight/></button><button @click="go('orders')"><Document/><span>订单、评价与售后</span><ArrowRight/></button><button @click="go('afterSales')"><Clock/><span>退款处理进度</span><ArrowRight/></button><button @click="go('bill')"><InfoFilled/><span>先吃后付与账单</span><ArrowRight/></button></section><p class="support-disclaimer">{{remote?'Java模拟服务模式：消息和留言由当前服务端会话保存，不调用真实AI或支付。':'本机沟通演示：可切换商家/平台身份手动回复，不会发送给真实客服。'}}</p>
</template>
<template v-else-if="mode==='supportChat'&&thread">
<section class="support-chat-heading"><img :src="thread.session.shopAvatar||'/avatar.svg'" alt="店铺头像"/><div><strong>{{thread.session.shopName}}</strong><small>{{remote?'Java模拟会话':'本机会话'}} · {{thread.session.id}}</small></div><button aria-label="刷新消息" @click="load"><Refresh/></button></section><p class="support-thread-tip">{{remote?'消息由当前Java模拟服务保存，按店铺权限读取':'消息保存在当前浏览器，商家端手动回复'}}；不代表真人或AI在线</p>
<p v-if="relatedChatOrder" class="support-thread-tip" data-testid="chat-order-context">正在咨询订单 {{relatedChatOrder.no||relatedChatOrder.id}} · {{relatedChatOrder.name}}；消息由你输入后发送</p>
<button v-if="historyMore" class="support-history-more" :disabled="historyBusy" @click="older">{{historyBusy?'正在读取':'读取更早消息'}}</button><div class="support-messages" data-testid="customer-support-messages"><article v-for="message in thread.messages" :key="message.id" class="support-message" :class="{mine:message.senderRole==='ROLE_USER'}"><small>{{message.senderLabel}} · {{time(message.createdAt)}}</small><div><p v-if="message.text">{{message.text}}</p><ServiceAttachment v-for="(file,index) in media(message)" :key="file.id||index" :attachment="file" compact/></div></article><div v-if="!thread.messages.length" class="support-empty">说说你想了解的餐品或订单问题吧<br>对方需切换商家身份才能回复</div></div>
<form class="support-chat-compose" data-testid="customer-support-composer" @submit.prevent="send"><ServiceUpload v-model="attachments" :disabled="busy" :context-key="route.fullPath" @busy="uploading=$event"/><div class="support-compose-row"><textarea v-model="text" maxlength="1000" placeholder="给本店发消息…" aria-label="给本店发消息" rows="2"></textarea><button type="submit" class="primary-pill" :disabled="busy||uploading||(!text.trim()&&!attachments.length)">发送</button></div></form>
</template>
<template v-else-if="mode==='supportTickets'">
<div class="support-list-heading"><h3>我的留言</h3><button class="primary-pill" @click="go('supportNew')"><Plus/>新留言</button></div><label class="support-archive-filter"><input v-model="includeArchived" type="checkbox" @change="page=1"/>含归档记录</label><div class="support-filters"><button v-for="value in ['ALL','OPEN','IN_PROGRESS','RESOLVED','CLOSED']" :key="value" :class="{active:ticketFilter===value}" @click="ticketFilter=value;page=1">{{value==='ALL'?'全部':labels[value]}}</button></div><button v-for="row in filteredTickets" :key="row.id" class="native-card support-ticket-card" @click="go('supportTicket',{id:row.id})"><div><span>{{row.shopName}}</span><b :class="row.status.toLowerCase()">{{row.archived?'已归档 · ':''}}{{labels[row.status]}}</b></div><h3>{{row.title}}</h3><p>{{row.content}}</p><footer><span>{{time(row.updatedAt||row.createdAt)}}</span><small>{{row.replyCount??row.replies?.length??0}}条回复 <ArrowRight/></small></footer></button><div class="support-pagination"><button :disabled="page<=1" @click="page--">上一页</button><span>{{page}} / {{Math.max(1,Math.ceil(ticketTotal/pageSize))}}</span><button :disabled="page*pageSize>=ticketTotal" @click="page++">下一页</button><select v-model.number="pageSize" @change="page=1"><option :value="10">10条</option><option :value="20">20条</option><option :value="50">50条</option></select></div><div v-if="!filteredTickets.length" class="native-empty">这里还没有留言<button class="primary-pill full" @click="go('supportNew')">填写新留言</button></div><p class="support-disclaimer">留言用于沟通，不会触发退款或改变账单。金额售后请从订单的“评价与售后”发起。</p>
</template>
<template v-else-if="mode==='supportNew'">
<section class="native-card"><h3 class="accent-title">给店铺留言</h3><form class="native-form support-ticket-form" data-testid="customer-ticket-form" @submit.prevent="submitTicket"><label>选择店铺<select v-model="form.unitId" required aria-label="留言店铺"><option value="" disabled>请选择具体店铺</option><option v-for="store in shops" :key="store.id" :value="store.id">{{store.nickname}}</option></select></label><label>关联订单（选填）<select v-model="form.orderId" aria-label="关联订单"><option value="">不关联订单</option><option v-for="order in relatedOrders" :key="order.id" :value="order.id">{{order.name}} · {{order.no}}</option></select></label><label>留言标题<input v-model="form.title" required maxlength="200" placeholder="例如：想咨询套餐内容" aria-label="留言标题"/></label><label>留言内容<textarea v-model="form.content" rows="5" required maxlength="1500" placeholder="描述你的问题或建议，请使用示例资料" aria-label="留言内容"></textarea></label><label>处理优先级<select v-model="form.priority" aria-label="处理优先级"><option value="LOW">低</option><option value="MEDIUM">中</option><option value="HIGH">高</option></select></label><ServiceUpload v-model="attachments" :disabled="busy" :context-key="route.fullPath" @busy="uploading=$event"/><p>{{remote?'附件由当前模拟服务保存':'附件只保存在本机'}}，不会进入真实客服或支付渠道。</p><button class="primary-pill full" type="submit" :disabled="busy||uploading">提交留言</button></form></section>
</template>
<template v-else-if="mode==='supportTicket'&&ticket">
<section class="support-ticket-state"><small>{{ticket.id}} · {{ticket.shopName}}</small><h2>{{ticket.archived?'已归档 · ':''}}{{labels[ticket.status]}}</h2><p>{{ticket.title}}</p></section><section class="native-card"><p class="support-body-text">{{ticket.content}}</p><ServiceAttachment v-for="(file,index) in media(ticket)" :key="file.id||index" :attachment="file"/><small class="support-muted">{{time(ticket.createdAt)}} · {{priorities[ticket.priority]||ticket.priority}}优先级{{ticket.orderId?' · 关联订单'+ticket.orderId:''}}</small></section><section class="native-card"><h3 class="accent-title">沟通记录</h3><article v-for="reply in ticket.replies" :key="reply.id" class="support-ticket-reply"><strong>{{reply.senderLabel||reply.authorLabel||reply.senderName}}</strong><small>{{time(reply.createdAt)}}</small><p>{{reply.text}}</p><ServiceAttachment v-for="(file,index) in media(reply)" :key="file.id||index" :attachment="file"/></article><p v-if="!ticket.replies.length" class="support-empty">等待本店或平台处理，可切换对应体验身份回复</p><form v-if="ticket.canReply" class="native-form" @submit.prevent="replyTicket"><textarea v-model="text" required maxlength="1000" rows="3" placeholder="补充问题或回复处理意见" aria-label="补充留言"></textarea><ServiceUpload v-model="attachments" :disabled="busy" :context-key="route.fullPath" @busy="uploading=$event"/><button class="primary-pill full" type="submit" :disabled="busy||uploading||!text.trim()">发送补充</button></form></section><section class="native-card"><h3 class="accent-title">处理进度</h3><div v-for="(entry,index) in ticket.history" :key="index" class="support-history"><strong>{{historyLabels[entry.type]||entry.type}}</strong><small>{{time(entry.at||entry.createdAt)}}</small><p>{{entry.note||entry.text||'记录已保存'}}{{entry.toStatus?' · '+labels[entry.toStatus]:''}}</p></div></section><div class="support-ticket-actions"><button v-if="ticket.availableStatuses?.includes('CLOSED')" class="support-outline" :disabled="busy" @click="setStatus('CLOSED')">关闭留言</button><button v-if="ticket.availableStatuses?.includes('OPEN')" class="primary-pill" :disabled="busy" @click="setStatus('OPEN')">重新打开留言</button></div><div class="support-ticket-actions"><button v-if="ticket.canArchive" class="support-outline" :disabled="busy" @click="archive(false)">归档（可恢复）</button><button v-if="ticket.canRestore" class="primary-pill" :disabled="busy" @click="archive(true)">恢复留言</button></div><p class="support-disclaimer">留言状态不会更改订单、额度或退款记录。金额售后另走独立审核流程。</p>
</template>
<div v-else class="native-empty">{{error||'记录不存在或不属于当前顾客'}}<button class="primary-pill full" @click="go('support')">返回服务中心</button></div>
<div v-if="picker" class="native-overlay" @click.self="picker=false"><section class="native-sheet support-store-picker"><button class="sheet-close" @click="picker=false">×</button><h3>联系哪家店铺？</h3><p>会话按店铺分别保存，商家只能看到本店咨询</p><button v-for="store in shops" :key="store.id" class="support-session" @click="start(store)"><img :src="store.avatarUrl||'/avatar.svg'" alt="店铺头像"/><span><strong>{{store.nickname}}</strong><small>{{store.info||'示例门店'}}</small></span><ArrowRight/></button></section></div>
